'use strict';
let personalProfiles=[],personalSelected=localStorage.getItem('yoga-character-id')||'',personalWorking=false;
function personalProfile(){return personalProfiles.find(p=>p.id===personalSelected);}
function personalCompatible(p,x){return !p.posture||['base','arms','legs','spine'].every(k=>!p.posture[k]||!x.posture[k]||['unknown','other'].includes(p.posture[k])||['unknown','other'].includes(x.posture[k])||p.posture[k]===x.posture[k]);}
function personalPose(p){if(p.poseId)return YOGA_POSE_CATALOG.entries.find(x=>x.id===p.poseId&&personalCompatible(p,x));const key=String(p.name||'').replace(/\s/g,'').toLowerCase();const exact=YOGA_POSE_CATALOG.entries.filter(x=>[x.name,x.english,...x.aliases].some(n=>n.replace(/\s/g,'').toLowerCase()===key));if(exact.length===1&&personalCompatible(p,exact[0]))return exact[0];if(Number.isInteger(p.kind)){const found=YOGA_POSE_CATALOG.entries.filter(x=>x.artwork.assetIndexes.includes(p.kind));if(found.length===1&&personalCompatible(p,found[0]))return found[0];}return null;}
function personalFigure(p){const profile=personalProfile();if(!profile)return null;const pose=personalPose(p),url=pose&&profile.poses[pose.id]?`/api/characters/${profile.id}/${pose.id}.png`:null;return `<svg width="150" height="140" viewBox="0 0 150 140" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(p.name)}专属人物">${url?`<image href="${url}" width="150" height="140" preserveAspectRatio="xMidYMid meet"/>`:'<text x="75" y="65" text-anchor="middle" font-size="9" fill="#7b8970">专属动作尚未生成</text>'}</svg>`;}
function personalView(){const p=personalProfile(),list=state.items.map(personalPose).filter(Boolean),unique=[...new Set(list.map(x=>x.id))];return heading('','我的小人','可选功能：上传照片，生成用于课程贴纸的专属人物。','默认手绘风格')+`<div class="workspace"><section class="panel"><h2>我的专属小人</h2><p>上传照片后会自动生成人物，不需要额外确认。</p><label for="personal-photo">选择自己的照片</label><input id="personal-photo" type="file" accept="image/jpeg,image/png"><p class="hint">建议正面、单人、光线清楚。照片将发送到你已连接的绘图平台，生成成功后删除本机原照片；人物图保留在这台电脑。生成会使用该平台额度。</p><button id="personal-create" class="primary wide" ${personalWorking?'disabled':''}>生成我的小人</button><p id="personal-status" class="info" role="status">${esc(p?.error||p?.message||'先选择照片，再点击生成。')}</p>${personalProfiles.length?`<label>已保存的人物<select id="personal-select" ${personalWorking?'disabled':''}><option value="">使用原版小女孩</option>${personalProfiles.map((x,i)=>`<option value="${x.id}" ${personalSelected===x.id?'selected':''}>我的小人 ${personalProfiles.length-i}${x.outfit==='wrap'?' · 交叉领＋灯笼裤':x.outfit==='blue'?' · 雾蓝上衣':''}${x.avatar?'':' · 未完成'}</option>`).join('')}</select></label>`:''}${p?`<p>${Object.keys(p.poses).length} 个专属动作已保存，以后直接复用。</p>${!p.avatar?'<button id="personal-resume" class="secondary wide">继续生成人物</button>':`<p>当前课程 ${state.items.length} 条提示，可对应 ${unique.length} 个不同体式。${state.items.length-list.length} 条尚不能对应动作库。</p><button id="personal-course" class="primary wide" ${!unique.length||personalWorking?'disabled':''}>生成当前课程的专属动作</button><button id="personal-outfit" class="secondary wide">换一套衣服，只生成三个体式</button><button id="personal-try" class="secondary wide">先生成山式、战士二式、树式</button><button id="personal-preview-three" class="secondary wide">预览这三个体式</button>`}<button id="personal-delete" class="secondary wide">删除这个人物和全部图片</button>`:''}</section><section class="panel"><h2>人物与动作</h2>${p?.avatar?`<img class="personal-avatar" alt="我的专属小人" src="/api/characters/${p.id}/avatar.png"><div class="personal-grid">${Object.keys(p.poses).map(id=>`<div><img alt="${esc(YOGA_POSE_CATALOG.entries.find(x=>x.id===id)?.name||id)}" src="/api/characters/${p.id}/${id}.png"><p>${esc(YOGA_POSE_CATALOG.entries.find(x=>x.id===id)?.name||id)}</p></div>`).join('')}</div>`:'<div class="empty">生成后，你的小人会显示在这里。</div>'}<p class="hint">每个动作都使用同一人物图和动作库图片作参考。AI 插画的相似度和动作细节仍需检查。</p></section></div>`;}
async function personalRefresh(){personalProfiles=(await request('/api/characters')).filter(p=>p.status!=='rejected');if(personalSelected&&!personalProfile()){personalSelected='';localStorage.removeItem('yoga-character-id');}}
function personalNote(text){const el=document.querySelector('#personal-status');if(el)el.textContent=text;else notify(text);}
async function personalWait(id){while(true){const p=await request('/api/characters/'+id);const at=personalProfiles.findIndex(x=>x.id===id);if(at<0)personalProfiles.unshift(p);else personalProfiles[at]=p;personalNote(p.error||p.message);if(p.status!=='generating'){if(page==='character')render();if(p.status==='failed')throw Error(p.error||p.message);return p;}await new Promise(r=>setTimeout(r,2000));}}
function personalPost(path,data={}){return request(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});}
async function personalTask(fn){if(personalWorking)return;personalWorking=true;let error;try{await fn();}catch(e){error=e.message;}finally{await personalRefresh().catch(()=>{});personalWorking=false;render();if(error)personalNote(error);}}
async function personalReference(pose,characterId){const source=characterFigure(pose.id,pose.name)||figure(pose.artwork.assetIndexes[0]);const svg=await embedCharacterAtlases(source);const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const load=src=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});const [body,avatar]=await Promise.all([load(url),load('/api/characters/'+characterId+'/avatar.png')]);const c=document.createElement('canvas');c.width=1024;c.height=640;const ctx=c.getContext('2d');ctx.fillStyle='#fffdf5';ctx.fillRect(0,0,1024,640);ctx.fillStyle='#435a3b';ctx.font='20px sans-serif';ctx.fillText('LEFT: PERSON / IDENTITY',20,30);ctx.fillText('RIGHT: POSE ONLY',540,30);const fit=(img,x)=>{const scale=Math.min(480/img.width,580/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,x+(480-w)/2,50+(580-h)/2,w,h);};fit(avatar,10);fit(body,530);return c.toDataURL('image/png');}finally{URL.revokeObjectURL(url);}}
async function personalGenerate(ids){const id=personalSelected;for(const poseId of [...new Set(ids)]){const p=personalProfiles.find(x=>x.id===id);if(p.poses[poseId])continue;const pose=YOGA_POSE_CATALOG.entries.find(x=>x.id===poseId);if(!pose)continue;personalNote('正在准备 '+pose.name+'…');await personalPost(`/api/characters/${id}/poses`,{poses:[{poseId,reference:await personalReference(pose,id)}]});await personalWait(id);}notify('专属动作已保存，可以预览和打印。');}
function bindPersonal(){const on=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn;};on('personal-create',()=>personalTask(async()=>{const f=document.getElementById('personal-photo').files[0];if(!f)throw Error('请先选择一张照片。');if(f.size>6*1024*1024)throw Error('请选择6 MB以内的照片。');const photo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});personalNote('正在生成人物…');const p=await personalPost('/api/characters',{photo});personalSelected=p.id;localStorage.setItem('yoga-character-id',p.id);await personalWait(p.id);}));on('personal-resume',()=>personalTask(async()=>{await personalPost(`/api/characters/${personalSelected}/resume`);await personalWait(personalSelected);}));on('personal-course',()=>personalTask(()=>personalGenerate(state.items.map(personalPose).filter(Boolean).map(x=>x.id))));on('personal-outfit',()=>personalTask(async()=>{personalNote('正在更换服装…');const p=await personalPost('/api/characters/'+personalSelected+'/outfit');personalSelected=p.id;localStorage.setItem('yoga-character-id',p.id);await personalWait(p.id);await personalGenerate(['mountain','warrior-2','tree']);}));on('personal-try',()=>personalTask(()=>personalGenerate(['mountain','warrior-2','tree'])));on('personal-preview-three',personalPreviewThree);on('personal-delete',()=>personalTask(async()=>{if(!confirm('删除这个专属小人和全部动作图片？'))return;await personalPost(`/api/characters/${personalSelected}/delete`);personalSelected='';localStorage.removeItem('yoga-character-id');}));const select=document.getElementById('personal-select');if(select)select.onchange=()=>{personalSelected=select.value;localStorage.setItem('yoga-character-id',personalSelected);render();};}
async function embedPersonalImages(svg){const matches=[...new Set(svg.match(/\/api\/characters\/[a-f0-9-]{36}\/[a-z0-9-]+\.png/g)||[])];for(const url of matches){const r=await fetch(url);if(!r.ok)throw Error('专属人物图片无法读取');const blob=await r.blob(),data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});svg=svg.split(url).join(data);}return svg;}

function personalPreviewThree(){const p=personalProfile(),ids=['mountain','warrior-2','tree'];if(!ids.every(id=>p?.poses[id])){notify('三个体式还没生成完，请稍等。');return;}document.getElementById('personal-three')?.remove();const dialog=document.createElement('dialog');dialog.id='personal-three';dialog.innerHTML='<h2>三个体式样张</h2><div class="personal-grid">'+ids.map(id=>'<div><img alt="'+esc(YOGA_POSE_CATALOG.entries.find(x=>x.id===id).name)+'" src="/api/characters/'+p.id+'/'+id+'.png"><p>'+esc(YOGA_POSE_CATALOG.entries.find(x=>x.id===id).name)+'</p></div>').join('')+'</div><button id="personal-sample-download" class="primary">下载三个体式样张</button> <button id="personal-sample-close">关闭</button>';document.body.append(dialog);dialog.querySelector('#personal-sample-close').onclick=()=>dialog.close();dialog.querySelector('#personal-sample-download').onclick=async()=>{try{const svg='<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="500" viewBox="0 0 1200 500"><rect width="1200" height="500" fill="#fffdf5"/>'+ids.map((id,i)=>'<image href="/api/characters/'+p.id+'/'+id+'.png" x="'+(i*400)+'" y="0" width="400" height="440" preserveAspectRatio="xMidYMid meet"/><text x="'+(i*400+200)+'" y="475" text-anchor="middle" font-family="sans-serif" font-size="22" fill="#435a3b">'+esc(YOGA_POSE_CATALOG.entries.find(x=>x.id===id).name)+'</text>').join('')+'</svg>';download(await embedPersonalImages(svg),'我的小人-三个体式.svg','image/svg+xml');}catch{notify('样张读取失败，请稍后再试。');}};dialog.showModal();}
